"use client";

import { useId, useState, type ComponentProps } from "react";
import { Eye, EyeOff } from "lucide-react";
import { Google, GitHubDark } from "@ridemountainpig/svgl-react";
import { cn } from "cn";
import { Avatar } from "../components/avatar";
import { Badge } from "../components/badge";
import { Banner } from "../components/banner";
import { Button } from "../components/button";
import { Card } from "../components/card";

interface LoginProps extends Omit<ComponentProps<"form">, "title" | "action"> {
  title?: string;
  description?: string;
  brand?: string;
  showSocial?: boolean;
  onProviderLogin?: (provider: "google" | "github") => void;
  loading?: boolean;
  error?: string;
  forgotPasswordHref?: string;
  signupHref?: string;
}

function LoginLayout({ layout, title = "Welcome back", description = "Sign in to pick up where you left off.", brand = "Studio", showSocial = true, onProviderLogin, loading = false, error, forgotPasswordHref = "/forgot-password", signupHref = "/signup", onSubmit, className, children, ...props }: LoginProps & { layout: "card" | "split" | "minimal" }) {
  return (
    <div data-slot="login" data-layout={layout} className="@container w-full">
      <div className={cn(layout === "split" && "grid grid-cols-1 border border-border bg-card @xl:min-h-144 @xl:grid-cols-2")}>
      {layout === "split" && <aside className="flex min-w-0 flex-col justify-between gap-10 border-b border-border bg-muted p-8 @xl:border-r @xl:border-b-0">
        <div className="flex items-center gap-3"><span className="text-xl font-semibold">{brand}</span><Badge variant="neutral">Workspace</Badge></div>
        <div><figure className="max-w-xl border-l-2 border-border py-2 pl-6"><blockquote className="text-xl leading-relaxed">A little less friction. A lot more room to create.</blockquote><figcaption className="mt-4 text-sm text-muted-foreground">Alex Morgan · Designer</figcaption></figure><div className="mt-6"><Avatar name="Alex Morgan" size={40} /></div></div>
      </aside>}
      <Card title={title} description={description} className={cn("mx-auto max-w-md!", layout === "split" && "m-0! min-w-0 max-w-none! border-0 p-6 shadow-none @xl:flex @xl:flex-col @xl:justify-center @xl:p-10", layout === "minimal" && "border-0 bg-transparent! text-foreground shadow-none")}>
        <LoginForm {...props} title={title} showSocial={showSocial} onProviderLogin={onProviderLogin} loading={loading} error={error} forgotPasswordHref={forgotPasswordHref} signupHref={signupHref} onSubmit={onSubmit} className={className}>{children}</LoginForm>
      </Card>
      </div>
    </div>
  );
}

export function Login(props: LoginProps = {}) {
  return <LoginLayout {...props} layout="card" />;
}

export function LoginSplit(props: LoginProps = {}) {
  return <LoginLayout {...props} layout="split" />;
}

export function LoginMinimal(props: LoginProps = {}) {
  return <LoginLayout {...props} layout="minimal" />;
}

function LoginForm({ title, showSocial, onProviderLogin, loading, error, forgotPasswordHref, signupHref, onSubmit, className, children, ...props }: LoginProps) {
  const id = useId();
  return (
        <form {...props} aria-label={props["aria-label"] ?? title} className={cn("space-y-5", className)} onSubmit={event => { event.preventDefault(); onSubmit?.(event); }}>
          {error && <div role="alert"><Banner variant="destructive" dismissible={false} message={error} /></div>}
          {showSocial && <div>
            <div className="grid grid-cols-2 gap-3">
              <Button variant="outline" disabled={loading || !onProviderLogin} onClick={() => onProviderLogin?.("google")}><Google width={16} height={16} aria-hidden="true" />Google</Button>
              <Button variant="outline" disabled={loading || !onProviderLogin} onClick={() => onProviderLogin?.("github")}><GitHubDark width={16} height={16} aria-hidden="true" />GitHub</Button>
            </div>
            <div className="my-5 flex items-center gap-3 text-xs text-muted-foreground"><span className="h-px flex-1 bg-border" />Or continue with email<span className="h-px flex-1 bg-border" /></div>
          </div>}
          <div className="space-y-2">
            <label htmlFor={`${id}-email`} className="block text-sm font-medium">Email</label>
            <input id={`${id}-email`} name="email" type="email" autoComplete="email" placeholder="you@example.com" required disabled={loading} className="min-h-11 w-full border border-border bg-background px-3 text-sm focus-visible:outline-2 focus-visible:outline-ring disabled:opacity-50" />
          </div>
          <PasswordField id={id} loading={loading} forgotPasswordHref={forgotPasswordHref} />
          {children}
          <Button type="submit" className="w-full" disabled={loading || !onSubmit} aria-busy={loading}>{loading ? "Signing in…" : "Sign in"}</Button>
          {signupHref && <p className="text-center text-xs text-muted-foreground">New here? <a href={signupHref} className="font-medium text-foreground hover:underline focus-visible:outline-2 focus-visible:outline-ring">Create an account</a></p>}
        </form>
  );
}

function PasswordField({ id, loading, forgotPasswordHref }: { id: string; loading?: boolean; forgotPasswordHref?: string }) {
  const [visible, setVisible] = useState(false);
  return (
          <div className="space-y-2">
            <div className="flex items-center justify-between gap-3"><label htmlFor={`${id}-password`} className="text-sm font-medium">Password</label>{forgotPasswordHref && <a href={forgotPasswordHref} className="text-xs text-muted-foreground hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring">Forgot password?</a>}</div>
            <div className="relative">
              <input id={`${id}-password`} name="password" type={visible ? "text" : "password"} autoComplete="current-password" required disabled={loading} className="min-h-11 w-full border border-border bg-background pr-12 pl-3 text-sm focus-visible:outline-2 focus-visible:outline-ring disabled:opacity-50" />
              <Button variant="ghost" className="absolute inset-y-0 right-0 px-3" disabled={loading} aria-label={visible ? "Hide password" : "Show password"} aria-pressed={visible} onClick={() => setVisible(!visible)}>{visible ? <EyeOff size={16} aria-hidden="true" /> : <Eye size={16} aria-hidden="true" />}</Button>
            </div>
          </div>
  );
}

"use client";

import { useState } from "react";

interface AvatarProps {
  src?: string;
  name?: string;
  size?: number;
  className?: string;
}

export function Avatar({
  src,
  name = "Alex Morgan",
  size = 48,
  className = "",
}: AvatarProps = {}) {
  const [failedSrc, setFailedSrc] = useState<string>();
  const initials = name
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((word) => word[0])
    .join("")
    .toUpperCase();
  // Registry consumers can use any React framework and image URL.
  /* eslint-disable @next/next/no-img-element */
  return (
    <span
      role="img"
      aria-label={name}
      style={{ width: size, height: size }}
      className={`inline-flex shrink-0 items-center justify-center overflow-hidden border border-border bg-emerald-400/15 text-sm font-semibold text-emerald-300 ${className}`}
    >
      {src && failedSrc !== src ? (
        <img
          src={src}
          alt=""
          width={size}
          height={size}
          onError={() => setFailedSrc(src)}
          className="h-full w-full object-cover"
        />
      ) : (
        initials || "?"
      )}
    </span>
  );
}

import type { ComponentProps } from "react";

interface BadgeProps extends ComponentProps<"span"> {
  variant?: "neutral" | "info" | "success" | "warning" | "error" | "blue" | "purple" | "pink" | "teal" | "orange";
}

export function Badge({ children = "New release", variant = "success", className = "", ...props }: BadgeProps = {}) {
  const styles = {
    neutral: "bg-neutral-800 text-neutral-200",
    info: "bg-sky-400/10 text-sky-300",
    success: "bg-emerald-400/10 text-emerald-300",
    warning: "bg-amber-400/10 text-amber-300",
    error: "bg-red-400/10 text-red-300",
    blue: "bg-blue-400/10 text-blue-300",
    purple: "bg-purple-400/10 text-purple-300",
    pink: "bg-pink-400/10 text-pink-300",
    teal: "bg-teal-400/10 text-teal-300",
    orange: "bg-orange-400/10 text-orange-300",
  };
  return <span className={`inline-flex items-center border border-border px-2.5 py-1 text-xs font-medium ${styles[variant] ?? styles.success} ${className}`} {...props}>{children}</span>;
}

"use client";

import { useState, type ReactNode } from "react";

interface BannerProps {
  variant?: "primary" | "secondary" | "ghost" | "destructive";
  children?: ReactNode;
  message?: string;
  dismissible?: boolean;
  className?: string;
}

export function Banner({ variant = "primary", children, message = "A little update. A lot of possibilities. Explore what's new.", dismissible = true, className = "" }: BannerProps = {}) {
  const styles = {
    primary: "bg-primary text-primary-foreground",
    secondary: "bg-card text-card-foreground",
    ghost: "bg-transparent text-foreground",
    destructive: "bg-destructive text-destructive-foreground",
  };
  const [dismissed, setDismissed] = useState(false);
  if (dismissed) return null;
  return <div role="status" className={`flex items-center justify-between gap-4 border border-border px-5 py-4 text-sm ${styles[variant] ?? styles.primary} ${className}`}>
    <div>{children ?? message}</div>
    {dismissible && <button type="button" aria-label="Dismiss banner" onClick={() => setDismissed(true)} className="flex size-9 shrink-0 items-center justify-center hover:bg-black/10 focus-visible:outline-2 focus-visible:outline-current"><span aria-hidden="true">×</span></button>}
  </div>;
}

import type { ComponentProps } from "react";

interface ButtonProps extends ComponentProps<"button"> {
  variant?: "primary" | "secondary" | "ghost" | "destructive" | "outline";
}

export function Button({
  children = "Get started",
  variant = "primary",
  className = "",
  type = "button",
  ...props
}: ButtonProps = {}) {
  const styles = {
    primary: "bg-emerald-400 text-neutral-950 hover:bg-emerald-300",
    secondary: "bg-neutral-800 text-white hover:bg-neutral-700",
    ghost: "bg-transparent text-foreground hover:bg-muted",
    destructive: "bg-destructive text-destructive-foreground hover:bg-destructive/90",
    outline: "border border-border text-white hover:bg-neutral-800",
  };
  return (
    <button
      type={type}
      className={`inline-flex min-h-11 items-center justify-center gap-2 px-5 py-2 text-sm font-semibold transition-colors focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-emerald-400 disabled:pointer-events-none disabled:opacity-50 ${styles[variant] ?? styles.primary} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
}

import type { ComponentProps, ReactNode } from "react";

interface CardProps extends Omit<ComponentProps<"article">, "title"> {
  title?: string;
  description?: string;
  footer?: ReactNode;
}

export function Card({ title = "Room for your next idea", description = "A simple starting point for something great. Make it yours.", children, footer, className = "", ...props }: CardProps = {}) {
  return <article className={`w-full max-w-sm border border-border bg-card p-6 text-card-foreground shadow-sm ${className}`} {...props}>
    {title && <h3 className="text-lg font-semibold">{title}</h3>}
    {description && <p className="mt-2 text-sm leading-6 opacity-80">{description}</p>}
    {children && <div className={title || description || footer ? "mt-5" : "h-full min-h-0"}>{children}</div>}
    {footer && <footer className="mt-5 border-t border-border pt-4">{footer}</footer>}
  </article>;
}
